"""Text-to-SQL harness: draft -> execute -> targeted repair (<= env.max_calls policy calls).

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict   {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
IDENT = re.compile(r"\b(?:FROM|JOIN)\s+[\"'`\[]?([A-Za-z_][A-Za-z_0-9]*)", re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
RESERVED = {"select", "with", "values", "lateral", "unnest"}


def extract_sql(text):
    text = text or ""
    blocks = [b.strip() for b in SQL_BLOCK.findall(text) if b.strip()]
    cand = blocks[-1] if blocks else text.strip()
    cand = cand.strip().rstrip(";").strip()
    if not blocks:
        m = re.search(r"(?is)\b(select|with)\b.*", cand)
        if m:
            cand = m.group(0).strip()
    return cand.rstrip(";").strip()


def _tables(sql):
    out = []
    for t in IDENT.findall(sql or ""):
        tl = t.lower()
        if tl not in RESERVED and tl not in [x.lower() for x in out]:
            out.append(t)
    return out[:4]


def _fmt_rows(res, limit=6):
    lines = []
    for r in (res.get("rows") or [])[:limit]:
        cells = []
        for c in r:
            s = "NULL" if c is None else str(c)
            if len(s) > 60:
                s = s[:57] + "..."
            cells.append(s)
        lines.append(" | ".join(cells))
    return "\n".join(lines)


def _samples(env, sql, literals):
    """Real stored values from the tables the draft touches, so literals can be checked."""
    chunks = []
    for t in _tables(sql):
        try:
            res = env.execute('SELECT * FROM "%s" LIMIT 4' % t.replace('"', ""), max_rows=4)
        except Exception:
            continue
        if not res or not res.get("ok"):
            continue
        cols = res.get("columns") or []
        body = _fmt_rows(res, 4)
        if body:
            chunks.append("Table %s (%s):\n%s" % (t, ", ".join(map(str, cols)), body))
        # for each string literal used by the draft, show nearby stored values
        for lit in literals[:3]:
            probe = lit.strip().replace("'", "''")
            if not probe:
                continue
            for c in cols:
                cname = str(c).replace('"', "")
                q = ('SELECT DISTINCT "%s" FROM "%s" WHERE "%s" LIKE \'%%%s%%\' LIMIT 5'
                     % (cname, t.replace('"', ""), cname, probe))
                try:
                    r2 = env.execute(q, max_rows=5)
                except Exception:
                    continue
                if r2 and r2.get("ok") and r2.get("rows"):
                    vals = ", ".join(repr(r[0]) for r in r2["rows"])
                    chunks.append("Stored values in %s.%s matching %r: %s" % (t, cname, lit, vals))
                    break
    return "\n\n".join(chunks)[:2600]


def _suspicion(sql, res):
    notes = []
    lits = LITERAL.findall(sql or "")
    if any(l != l.strip() and l.strip() for l in lits):
        notes.append("A string literal has leading/trailing whitespace; with LIKE '%...%' this "
                     "usually matches nothing. Match the core word instead.")
    rows = res.get("rows") or []
    cols = res.get("columns") or []
    if rows and cols:
        for i in range(len(cols)):
            if all((len(r) > i and r[i] is None) for r in rows):
                notes.append("Every returned value of column %r is NULL - confirm this is the "
                             "column the question asks for." % str(cols[i]))
                break
    return notes


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 1200)
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (task["db_id"], schema, task["question"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    if task.get("hint"):
        user += "\nHint: " + task["hint"]
    user += ("\n\nWrite the query now. Before finalising, check that every string literal you compare "
             "against actually exists in the data in that exact form, that join keys point the right "
             "way, and that you select exactly the columns the question asks for.")

    messages = [{"role": "system", "content": env.prompt("system_prompt.md")},
                {"role": "user", "content": user}]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}

    budget = getattr(env, "max_calls", 2) or 2
    if budget < 2:
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = {"ok": False, "error": "execution raised", "rows": [], "columns": []}

    if res.get("ok"):
        notes = _suspicion(sql, res)
        if (res.get("n_rows") or 0) > 0 and not notes:
            return {"sql": sql}
        if (res.get("n_rows") or 0) == 0:
            problem = ("The draft executed but returned ZERO rows. Most likely a string literal does "
                       "not match the stored text exactly (case, spacing, abbreviation, punctuation), "
                       "a join key is reversed/wrong, or a filter is too strict. An empty answer is "
                       "only correct if the question genuinely asks about something absent.")
        else:
            problem = "The draft ran but may be wrong:\n- " + "\n- ".join(notes)
    else:
        problem = "The draft FAILED to execute. Error: %s" % str(res.get("error"))[:400]

    samples = _samples(env, sql, LITERAL.findall(sql))
    follow = ("%s\n\nDraft query:\n%s\n\n" % (problem, sql))
    if samples:
        follow += "Actual data sampled from the database (use these exact stored values):\n%s\n\n" % samples
    follow += ("Re-read the question and hint, fix the cause, and return ONE corrected SQLite query in "
               "a single ```sql block. Keep the columns the question asks for; do not add extra ones. "
               "If after checking the data the empty result really is correct, return the query unchanged.")
    messages = messages + [{"role": "assistant", "content": reply},
                           {"role": "user", "content": follow}]
    try:
        reply2 = env.chat(messages, max_tokens=max_tokens)
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = {"ok": False}
    if not res2.get("ok"):
        return {"sql": sql}
    if (res.get("n_rows") or 0) == 0 and (res2.get("n_rows") or 0) == 0 and not res.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}

